{"python":"import re

reported_ref = 'article:p35'
conf_acc_ref = 'supp.pdf/page4/R3C3'
conf_refs = [
    'supp.pdf/page4/R5C2', 'supp.pdf/page4/R5C3',
    'supp.pdf/page4/R7C2', 'supp.pdf/page4/R7C3'
]

assay_map = {
    'Sensitive': 1, 'sensitive': 1, 'SENSITIVE': 1,
    'Resistant': 0, 'resistant': 0, 'RESISTANT': 0,
    'Sensitivity': 1, 'sensitivity': 1,
    'Resistance': 0, 'resistance': 0
}
truth_map = {'PR': 1, 'pr': 1, 'PD': 0, 'pd': 0}

candidates = []
seen_refs = set()

for fn in ['supp.pdf', 'mmc1.pdf', 'mmc2.pdf']:
    if fn not in tables:
        continue
    for sh, obj in tables[fn].items():
        for ri, row in enumerate(obj.rows, start=1):
            pid_cells, assay_cells, truth_cells = [], [], []
            for cell in row:
                val = str(cell.get('value', '')).strip()
                if not val:
                    continue
                if re.search(r'\bP-?\d+\b', val):
                    pid_cells.append(cell)
                if val in assay_map:
                    assay_cells.append(cell)
                if val in truth_map:
                    truth_cells.append(cell)
            if pid_cells and assay_cells and truth_cells:
                pid_cell = pid_cells[0]
                assay_cell = assay_cells[0]
                truth_cell = truth_cells[0]
                key = (pid_cell.get('ref'), assay_cell.get('ref'), truth_cell.get('ref'))
                if key not in seen_refs:
                    seen_refs.add(key)
                    pid_match = re.search(r'P-?\d+', str(pid_cell.get('value', '')))
                    pid = pid_match.group(0) if pid_match else f'{fn}/{sh}/R{ri}'
                    candidates.append({
                        'id': f'{pid}:{fn}/{sh}/R{ri}',
                        'score': {'ref': assay_cell['ref'], 'map': {'Sensitive': 1, 'Resistant': 0, 'Sensitivity': 1, 'Resistance': 0, 'sensitive': 1, 'resistant': 0, 'sensitivity': 1, 'resistance': 0, 'SENSITIVE': 1, 'RESISTANT': 0}},
                        'truth': {'ref': truth_cell['ref'], 'map': {'PR': 1, 'PD': 0, 'pr': 1, 'pd': 0}},
                        '_pid': pid,
                        '_assay': assay_map[str(assay_cell['value']).strip()],
                        '_truth': truth_map[str(truth_cell['value']).strip()]
                    })
    if len(candidates) == 54:
        break

cm = {'TP': 0, 'FP': 0, 'FN': 0, 'TN': 0}
for c in candidates:
    if c['_assay'] == 1 and c['_truth'] == 1: cm['TP'] += 1
    elif c['_assay'] == 1 and c['_truth'] == 0: cm['FP'] += 1
    elif c['_assay'] == 0 and c['_truth'] == 1: cm['FN'] += 1
    elif c['_assay'] == 0 and c['_truth'] == 0: cm['TN'] += 1

print('candidate_n=', len(candidates))
print('confusion=', cm)
if candidates:
    print('first_candidates=', candidates[:5])

ok = (len(candidates) == 54 and cm == {'TP': 21, 'FP': 5, 'FN': 4, 'TN': 24})
records = []
if ok:
    for c in candidates:
        records.append({'id': c['id'], 'score': c['score'], 'truth': c['truth']})

fields = {
    'unit': {'value': 'organoid_line', 'evidence': [reported_ref], 'explanation': 'The 83.3% accuracy denominator is 54 LCOs derived from 36 patients, not 54 independent patients.'},
    'platform': {'value': 'organoid', 'evidence': [reported_ref], 'explanation': 'Lung cancer organoid drug sensitivity testing.'},
    'readout': {'value': 'viability', 'evidence': ['article:p128'], 'explanation': 'Predictor is the day-4 ATP luminance ratio of treated to untreated organoids.'},
    'direction': {'value': 'lower_sensitive', 'evidence': ['article:p128'], 'explanation': 'A lower treated-to-control ATP luminance ratio indicates greater drug sensitivity; source rows also use Sensitive versus Resistant calls.'},
    'threshold_rule': {'value': 'categorical', 'evidence': conf_refs, 'explanation': 'The evaluated source predictions are Sensitive versus Resistant calls; no global numeric cutoff is supplied.'},
    'threshold_timing': {'value': 'not_reported', 'evidence': ['article:p102'], 'explanation': 'The paper reports ROC evaluation but states that precise cutoff values were not yet defined.'},
    'patient_mapping': {'value': 'individual_available', 'evidence': [reported_ref], 'explanation': 'Patient identifiers and matched LCO results are available in the supplemental comparison table.'},
    'regimen_match': {'value': 'matched', 'evidence': [reported_ref], 'explanation': 'Only cases whose clinical regimens were identical to the LCO-DST regimen were included.'},
    'n_units': {'value': 54, 'evidence': [reported_ref, conf_acc_ref], 'explanation': 'Fifty-four matched LCO treatment comparisons; confusion matrix sums to 54.'},
    'split': {'value': 'same_cohort', 'evidence': [reported_ref, 'article:p102'], 'explanation': 'A real-world observational cohort with no separate held-out validation cohort.'}
}

if ok:
    contract_status = 'computed'
    blocked_reason = None
else:
    contract_status = 'blocked'
    blocked_reason = 'Could not identify 54 row-level source records with independently referenced LCO Sensitive/Resistant predictions and clinical PR/PD outcomes; parsed rows=%s and confusion=%s.' % (len(candidates), cm)

CONTRACT = {
    'status': contract_status,
    'fields': fields,
    'headline': {
        'metric': 'accuracy',
        'reported': 0.8333333333333334,
        'reported_evidence': [reported_ref, conf_acc_ref],
        'threshold': None,
        'op': '==',
        'score_direction': 'higher',
        'records': records,
        'blocked_reason': blocked_reason
    },
    'notes': ['Published confusion matrix: Sensitive/PR=21, Sensitive/PD=5, Resistant/PR=4, Resistant/PD=24; accuracy=(21+24)/54=0.8333333.', 'Clinical sensitivity and specificity in the article are 84.0% and 82.8%, respectively.']
}"}
